-- Oracle EBS R12 -> canonical PO_LINE (ORACLE_EBS). Generated by tools/build_silver_sql.py.
SELECT 'ORACLE_EBS' AS SOURCE_SLOT, 'Oracle EBS R12' AS SOURCE_SYSTEM, 'ORACLE_EBS' AS COMPANY_CODE, 'ORACLE_EBS' AS PLANT, h.SEGMENT1 AS PO_NUMBER, l.LINE_NUM::STRING AS PO_ITEM, h.VENDOR_ID::STRING AS SUPPLIER_ID,
  l.ITEM_NUMBER AS MATERIAL, l.ITEM_DESCRIPTION AS ITEM_TEXT, l.CATEGORY_CODE AS MATERIAL_GROUP, l.QUANTITY, l.UNIT_MEAS_LOOKUP_CODE AS UOM,
  l.UNIT_PRICE AS NET_PRICE, l.QUANTITY * l.UNIT_PRICE AS NET_VALUE, h.CURRENCY_CODE AS CURRENCY, h.CREATION_DATE AS PO_DATE,
  ll.NEED_BY_DATE AS DELIVERY_DATE, NULL::STRING AS CONTRACT_ID
FROM {{ source('src_oracle_ebs', 'po_lines_all') }} l JOIN {{ source('src_oracle_ebs', 'po_headers_all') }} h ON h.PO_HEADER_ID = l.PO_HEADER_ID
LEFT JOIN {{ source('src_oracle_ebs', 'po_line_locations_all') }} ll ON ll.PO_LINE_ID = l.PO_LINE_ID WHERE h.TYPE_LOOKUP_CODE = 'STANDARD'
